(()=>{
const farm=!!document.querySelector('#farmScene');
const guide=document.querySelector('.trial-guide');if(guide)guide.querySelector('summary').textContent='처음 시작하는 방법';
const notice=document.createElement('div');notice.className='first-harvest-notice';notice.hidden=true;notice.setAttribute('role','status');notice.innerHTML='<div><b>첫 수확! 상추 2개가 보관함에 들어갔어요.</b><p>6개 모으면 당근 씨앗이 열려요.</p></div><button type=button>계속하기</button>';if(farm)document.querySelector('.farm-bottom').before(notice);let noticeKey='',delivered=false,visualPending=false,previous=null;window.addEventListener('farm-visual-harvest-start',()=>{visualPending=true;notice.hidden=true});window.addEventListener('farm-visual-harvest-cancel',()=>{visualPending=false});window.addEventListener('farm-visual-harvest-end',()=>{visualPending=false;delivered=true;tidy()});notice.querySelector('button').onclick=()=>{try{localStorage.setItem(noticeKey,'seen')}catch{}notice.hidden=true};
function tidy(){if(!farm)return;const n=state.farm?.picked||0;document.body.dataset.firstHarvest=String(n===0);noticeKey='shiny-first-harvest:'+((window.classroomActive&&classroomData.me.id)||'practice');let seen=false;try{seen=localStorage.getItem(noticeKey)==='seen'}catch{}if(previous===null||previous.key!==noticeKey){previous={key:noticeKey,n};delivered=false}else{if(n>previous.n&&!window.farm3DReady)delivered=true;previous.n=n}notice.hidden=n===0||seen||visualPending||!delivered; document.querySelectorAll('.seed-picker button').forEach((b,i)=>{b.hidden=i>0&&b.disabled});}
if(farm){const old=render;render=function(){old();tidy()};tidy();const info=document.createElement('p');info.className='activity-intro';info.textContent='퀴즈로 직업을 알아보고, 공동 도시락에 작물을 보태거나 잠깐 머지 놀이를 즐겨 보세요.';document.querySelector('.compact-activities').prepend(info);}
})();
